"use strict";
import { useCallback } from "react";
import { useQueryClient } from "@tanstack/react-query";
const POSITION_QUERY_PREFIXES = [
  ["abstract-position"],
  ["unified-positions"],
  ["abstract-positions-centralized"]
];
export function usePositionQueryRefresher(delayMs = 8e3) {
  const queryClient = useQueryClient();
  return useCallback(async () => {
    console.log("\u{1F504} [POSITIONS] Invalidating position queries...");
    await Promise.all(
      POSITION_QUERY_PREFIXES.map((key) => queryClient.invalidateQueries({ queryKey: key }))
    );
    setTimeout(() => {
      console.log("\u{1F504} [POSITIONS] Force refetching position queries after delay...");
      POSITION_QUERY_PREFIXES.forEach((key) => {
        queryClient.refetchQueries({ queryKey: key });
      });
    }, delayMs);
  }, [queryClient, delayMs]);
}
